update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-tours/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Tours et en Touraine","mecanisme":"Beaucoup d''ateliers tourangeaux font tourner des machines plus âgées que leur documentation : rotatives, façonnage, presses reprises d''une génération à l''autre. Nous entretenons ces parcs, nous les fiabilisons et nous les rétrofitons quand la pièce n''existe plus. Nos techniciens se déplacent partout en France.","cta":"Demander une intervention à Tours","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés inclus."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus après entretien technique et comportemental, résultats partagés"},{"valeur":"J-90 à J-30","libelle":"la fenêtre de préparation d''un arrêt technique, avec restitution à la demi-journée"}]},{"type":"probleme","punchline":"Une chambre froide remonte en température un samedi. Le stock ne se rattrape pas, et le constructeur du groupe froid n''existe plus depuis dix ans.","puces":[{"accroche":"Les machines anciennes cachent leur usure.","texte":"Cames, chaînes, réglages : la dérive s''installe avant de casser quelque chose de cher."},{"accroche":"La pièce d''origine devient introuvable.","texte":"Sans arbitrage entre reprise, adaptation et rétrofit, l''arrêt se prolonge de semaines."},{"accroche":"Le froid et l''eau glacée arrêtent tout d''un coup.","texte":"Une utilité qui lâche emporte plusieurs ateliers à la fois."},{"accroche":"Les sites qualifiés exigent la trace écrite.","texte":"Pharmacie et cosmétique demandent un document, pas un accord oral."},{"accroche":"Le préventif recule dès que le correctif accélère.","texte":"La GMAO se remplit de reports, et le budget bascule du mauvais côté."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Entretien des parcs anciens","texte":"reprise de jeux, réglages, remplacement d''organes d''usure, usinage de pièces quand le catalogue ne suit plus."},"benefice":"Votre machine continue de produire au lieu d''attendre un remplacement complet."},{"prestation":{"accroche":"Rétrofit et fiabilisation","texte":"automates en fin de vie sauvegardés, migrés, supervision remise à niveau."},"benefice":"Vous sortez de la dépendance à une carte introuvable."},{"prestation":{"accroche":"Utilités suivies au même titre que les lignes","texte":"froid, eau glacée, air comprimé, pompage, régulation."},"benefice":"Un défaut d''utilité cesse d''être la panne que personne n''avait anticipée."},{"prestation":{"accroche":"Contrôle géométrique des machines d''usinage","texte":"alignements, paliers, broches, reprise de précision."},"benefice":"La qualité pièce se tient sans attendre le rebut pour s''en apercevoir."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [robotique](/expertises/robotique/), [hydraulique](/expertises/hydraulique/), [soudure](/expertises/soudure/)."},"benefice":"Un diagnostic qui croise trois métiers reste un seul interlocuteur."},{"prestation":{"accroche":"Arrêt technique préparé de J-90 à J-30","texte":", restitution à la demi-journée."},"benefice":"Le redémarrage tombe à la date annoncée, coordination des corps de métier comprise."}],"prose":[{"texte":"Le [bureau d''études](/offres/bureau-etudes/) prend le relais pour les modifications lourdes : implantation, transfert d''installation, mise en conformité. Les plateformes de l''axe autoroutier relèvent de la [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"machine, symptôme, criticité, adresse du site. Dix minutes suffisent à trier les priorités."},{"titre":"Nous vous rappelons dans l''heure","texte":"le profil disponible vous est nommé, ses résultats d''évaluation sont communicables sur demande."},{"titre":"Le devis précède le déplacement","texte":"périmètre, conditions, chiffrage écrit, options d''astreinte comprises."},{"titre":"L''intervention respecte vos règles d''accès","texte":"accueil sécurité, plan de prévention, consignation, puis diagnostic."},{"titre":"La réparation ou la solution provisoire sécurisée","texte":"le choix est documenté, la sécurité passe avant l''urgence."},{"titre":"Le compte rendu part dans votre GMAO","texte":"cause racine, pièces, préconisations, organes à surveiller."}]},{"type":"garanties","puces":[{"accroche":"Un arbitrage chiffré avant le remplacement","texte":"réparation, reprise ou rétrofit, chaque option est comparée avec son coût et sa durée de vie restante."},{"accroche":"Le profil présenté avant l''arrivée","texte":"10 % des candidats retenus après entretien technique et comportemental, résultats d''évaluation partagés."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste dépend de votre localisation précise, annoncé avant d''engager le déplacement."}]},{"type":"cta","question":"Besoin de savoir si votre machine vaut encore une réparation ?","bouton":"Demander une intervention à Tours","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-tours/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un technicien polyvalent intégré pour tenir un parc machines hétérogène en forte cadence","texte":"papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Un technicien intégré pendant l''arrêt estival pour tenir les équipements critiques","texte":"été 2025, équipe partiellement en congés","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Un électromécanicien habilité risque chimique RC1 mobilisé six mois sur un site de traitement des eaux industrielles","texte":"remise en état complète","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"1 à 3 techniciens en renfort des équipes maintenance sur plusieurs sites de production, depuis octobre 2024","texte":"disponibilité machine tenue semaine après semaine","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Six techniciens en permanence sur un contrat de préventif annuel, prise en charge complète réalisée en un mois","texte":"depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Tours, alors que votre siège est à Lyon ?","reponse":"Oui, et nous préférons le dire que l''inventer : aucune vitrine en centre-ville de Tours. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nos techniciens se déplacent partout en France, en se relayant selon la charge. Votre demande est rappelée dans l''heure aux horaires ouvrés. Le technicien arrive préparé sur votre machine, c''est la seule chose qui change votre journée."},{"question":"Quelles communes couvrez-vous en Touraine ?","reponse":"Tours, Saint-Pierre-des-Corps, Joué-lès-Tours, Saint-Avertin, Chambray-lès-Tours, La Riche, Saint-Cyr-sur-Loire, Parçay-Meslay et Monnaie, puis Amboise, Loches et Chinon. L''axe se traite d''un seul tenant vers Blois, Orléans, Le Mans et Poitiers."},{"question":"Pouvez-vous entretenir une machine dont le constructeur a disparu ?","reponse":"Oui, c''est un cas courant en Touraine. Relevés, reprise de cotes, adaptation ou usinage de pièces, migration d''automate quand l''électronique lâche : chaque option est chiffrée avant décision."},{"question":"Pouvez-vous reprendre un préventif en retard ?","reponse":"Oui. Nous repartons de l''état du parc et de l''historique de pannes. Le tri se fait par criticité, jusqu''à revenir à un rythme tenable pour votre équipe, sans arrêter la production."},{"question":"Intervenez-vous sur les machines-outils et les lignes automatisées ?","reponse":"Oui : commandes numériques, lignes de conditionnement, cellules robotisées ABB et Fanuc, aides à la manutention. Le diagnostic croise mécanique, électricité et automatisme, ce que peu de prestataires tiennent dans une seule équipe."},{"question":"Que contient un contrat de maintenance ?","reponse":"Périmètre, fréquences, méthode, indicateurs suivis, conditions de sortie, tout est écrit. L''abonnement [Zéro arrêt](/offres/zero-arret/) est chiffré sur devis, engagement type 6 mois renouvelable, après un diagnostic gratuit du parc."}]},{"type":"ctaFinal","question":"Besoin de préparer un arrêt technique sans découvrir les imprévus sur place ?","bouton":"Demander une intervention à Tours","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-tours/';
